const input = $input.first().json;

const query = input.query ?? {};
const params = input.params ?? {};
const headers = input.headers ?? {};

const allowedScenarios = [
  'happy',
  'unauthorized',
  'forbidden',
  'primary_rate_limit',
  'secondary_rate_limit',
  'server_error',
  'timeout',
  'invalid_payload',
  'page2_error',
  'pagination_101',
  'page_limit_11',
  'metadata_change',
];

const scenario = String(query.scenario ?? 'happy')
  .trim()
  .toLowerCase();

const page = Math.max(
  1,
  Number.parseInt(query.page ?? '1', 10) || 1
);

const attempt = Math.max(
  0,
  Number.parseInt(query.attempt ?? '0', 10) || 0
);

return [
  {
    json: {
      resource: input.resource,

      username: String(params.username ?? 'octocat'),

      scenario,
      scenario_valid: allowedScenarios.includes(scenario),

      page,
      attempt,

      request_headers: headers,

      // Em versões/configurações onde o Webhook expõe a URL,
      // conseguimos reutilizá-la para montar o Link da paginação.
      request_url: input.webhookUrl ?? null,
    },
  },
];

const input = $input.first().json;

const {
  resource,
  username,
  scenario,
  page,
  attempt,
  request_headers,
  request_url,
} = input;

const nowEpoch = Math.floor(Date.now() / 1000);

const requestId =
  `P01-${resource.toUpperCase()}-${scenario.toUpperCase()}-${attempt}`;


// --------------------------------------------------
// Helpers
// --------------------------------------------------

function profileFixture() {
  return {
    login: username,
    id: 1001,
    node_id: 'P01_USER_1001',
    avatar_url: 'https://example.invalid/avatar.png',
    html_url: `https://github.com/${username}`,
    type: 'User',
    name: 'P01 Test User',
    public_repos: 3,
  };
}


function repo(id, name) {
  return {
    id,
    name,
    full_name: `${username}/${name}`,
    owner: {
      login: username,
    },
    private: false,
    html_url: `https://github.com/${username}/${name}`,
    visibility: 'public',
  };
}


function repositoryFixture(currentPage) {

  if (scenario === 'pagination_101') {
    if (currentPage === 1) {
      const items = [];
      for (let i = 0; i < 100; i++) {
        items.push(
          repo(3001 + i, 'bulk-' + String(i + 1).padStart(3, '0'))
        );
      }
      return items;
    }
    if (currentPage === 2) {
      return [repo(3101, 'bulk-101')];
    }
    return [];
  }

  if (scenario === 'page_limit_11') {
    if (currentPage >= 1 && currentPage <= 11) {
      return [repo(4000 + currentPage, 'page-' + currentPage)];
    }
    return [];
  }

  if (currentPage === 1) {
    return [
      repo(2001, 'project-alpha'),
      repo(2002, 'project-beta'),
    ];
  }

  if (currentPage === 2) {
    return [
      repo(2003, 'project-gamma'),
    ];
  }

  return [];
}


function successBody() {
  return resource === 'profile'
    ? profileFixture()
    : repositoryFixture(page);
}


// --------------------------------------------------
// Default response
// --------------------------------------------------

let statusCode = 200;
let body = successBody();

let rateLimitLimit = '60';
let rateLimitRemaining = '57';
let rateLimitReset = String(nowEpoch + 3600);

let retryAfter = null;
let link = null;


// --------------------------------------------------
// Scenario
// --------------------------------------------------

switch (scenario) {

  case 'happy':
    break;


  case 'unauthorized':

    statusCode = 401;

    body = {
      message: 'Bad credentials',
    };

    break;


  case 'forbidden':

    statusCode = 403;

    rateLimitRemaining = '100';

    body = {
      message: 'Resource not accessible by integration',
    };

    break;


  case 'primary_rate_limit':

    if (attempt === 0) {

      statusCode = 403;

      rateLimitRemaining = '0';

      // curto de propósito para teste
      rateLimitReset = String(nowEpoch + 2);

      body = {
        message: 'API rate limit exceeded',
      };
    }

    break;


  case 'secondary_rate_limit':

    if (attempt === 0) {

      statusCode = 429;

      retryAfter = '2';

      body = {
        message:
          'You have exceeded a secondary rate limit.',
      };
    }

    break;


  case 'server_error':

    statusCode = 500;

    body = {
      message: 'Internal Server Error',
    };

    break;


  case 'timeout':

    // O Wait anterior já causou o comportamento
    // de timeout. Caso o cliente continue conectado,
    // respondemos normalmente.
    statusCode = 200;
    body = successBody();

    break;


  case 'page2_error':

    if (resource === 'repos' && page === 2) {
      statusCode = 500;
      body = { message: 'Internal Server Error on repository page 2' };
    }
    break;

  case 'pagination_101':
  case 'page_limit_11':
    break;


  case 'metadata_change':

    if (resource === 'repos' && page === 1) {

      let callIndex = 0;

      try {
        const sd = $getWorkflowStaticData('global');
        callIndex = Number(sd.metadata_change_calls ?? 0) || 0;
        sd.metadata_change_calls = callIndex + 1;
      } catch (e) {
        callIndex = attempt;
      }

      if (callIndex === 0) {
        body = [
          {
            ...repo(2001, 'project-alpha'),
            language: 'JavaScript',
            description: 'metadata v1',
          },
        ];
      } else {
        body = [
          {
            ...repo(2001, 'project-alpha-renamed'),
            language: 'Python',
            description: 'metadata v2',
          },
        ];
      }
    }

    break;


  case 'invalid_payload':

    statusCode = 200;

    if (resource === 'profile') {

      // Perfil válido: o caso exercita a validação de repositórios.
      body = profileFixture();

    } else {

      // owner.login propositalmente ausente
      body = [
        {
          id: 2999,
          name: 'invalid-repository',
          full_name: `${username}/invalid-repository`,
          owner: {},
          visibility: 'public',
        },
      ];
    }

    break;


  default:

    statusCode = 400;

    body = {
      message: `Unknown simulator scenario: ${scenario}`,
    };
}


// --------------------------------------------------
// Pagination
// --------------------------------------------------

if (
  statusCode === 200 &&
  resource === 'repos' &&
  scenario !== 'invalid_payload' &&
  (
    page === 1 ||
    (scenario === 'page_limit_11' && page >= 1 && page <= 10)
  )
) {

  let baseUrl = request_url;

  // fallback caso webhookUrl não esteja disponível
  if (!baseUrl) {

    const headers = request_headers ?? {};

    const proto =
      String(
        headers['x-forwarded-proto'] ?? 'http'
      )
        .split(',')[0]
        .trim();

    const host =
      headers['x-forwarded-host'] ??
      headers.host ??
      'localhost:5678';

    baseUrl =
      `${proto}://${host}` +
      `webhook-test/3da72337-4263-4f71-bbb2-a8c8dea89093/p01/github/users/` +
      `${encodeURIComponent(username)}/repos`;

  }

  baseUrl = String(baseUrl).split('?')[0];
  console.log(baseUrl)
  console.log('log')


  const nextPage =
    scenario === 'page_limit_11' ? page + 1 : 2;

  link =
    `<${baseUrl}?scenario=${encodeURIComponent(scenario)}&page=${nextPage}&attempt=${attempt}>; rel="next"`;
}


// --------------------------------------------------
// Output
// --------------------------------------------------

return [
  {
    json: {
      ...input,

      response: {
        status_code: statusCode,

        body,

        headers: {
          content_type: 'application/json',
          request_id: requestId,

          rate_limit_limit: rateLimitLimit,
          rate_limit_remaining: rateLimitRemaining,
          rate_limit_reset: rateLimitReset,

          retry_after: retryAfter,
          link: link
        },
      },
    },
  },
];

